2	use crate::cards::CardRegistry;
3	use crate::events::{GameEvent, DamageTarget};
4	use crate::ids::{ObjectId, PlayerId};
5	use crate::state::{CombatState, GameState, LogLevel};
6	use crate::types::{Keyword, Zone};
7	
8	/// Set up attackers. Validates and taps them.
9	/// Creatures with vigilance don't tap when attacking.
10	pub fn declare_attackers(
11	    state: &mut GameState,
12	    attackers: &[(ObjectId, PlayerId)],
13	    registry: &CardRegistry,
14	) {
15	    let mut combat = CombatState::new();
16	
17	    for &(attacker_id, defending_player) in attackers {
18	        // Vigilance: don't tap when attacking.
19	        let has_vigilance = state.has_keyword(attacker_id, Keyword::Vigilance, registry);
20	        if !has_vigilance {
21	            if let Some(obj) = state.get_object_mut(attacker_id) {
22	                obj.tapped = true;
23	                state.events.push(GameEvent::Tapped { object: attacker_id });
24	            }
25	        }
26	        combat.attackers.insert(attacker_id, defending_player);
27	        combat.blocker_assignments.insert(attacker_id, Vec::new());
28	    }
29	
30	    state.events.push(GameEvent::AttackersDeclared {
31	        attackers: attackers.to_vec(),
32	    });
33	
34	    state.combat = Some(combat);
35	}
36	
37	
38	/// Set up blockers. Validates assignments.
39	pub fn declare_blockers(
40	    state: &mut GameState,
41	    assignments: &[(ObjectId, ObjectId)], // (blocker, attacker)
42	) {
43	    if let Some(combat) = &mut state.combat {
44	        for &(blocker_id, attacker_id) in assignments {
45	            if let Some(blockers) = combat.blocker_assignments.get_mut(&attacker_id) {
46	                blockers.push(blocker_id);
47	            }
48	        }
49	    }
50	
51	    state.events.push(GameEvent::BlockersDeclared {
52	        assignments: assignments.to_vec(),
53	    });
54	}
55	
56	/// Set up blockers with validation. Filters out illegal block assignments
57	/// (e.g., non-flyer blocking a flyer, or menace with only 1 blocker).
58	pub fn declare_blockers_with_registry(
59	    state: &mut GameState,
60	    assignments: &[(ObjectId, ObjectId)],
61	    registry: &CardRegistry,
62	) {
63	    let valid: Vec<_> = assignments.iter()
64	        .filter(|&&(blocker, attacker)| can_block_attacker(state, blocker, attacker, registry))
65	        .cloned()
66	        .collect();
67	
68	    // Minimum blocker enforcement: for attackers with menace or MinimumBlockers
69	    // effects, verify they have enough blockers. If not, remove the block
70	    // assignments for that attacker (can't be blocked by fewer than N creatures).
71	    let mut blocker_counts: std::collections::HashMap<ObjectId, usize> = std::collections::HashMap::new();
72	    for &(_, attacker) in &valid {
73	        *blocker_counts.entry(attacker).or_insert(0) += 1;
74	    }
75	
76	    // Determine minimum blocker requirement for each attacker.
77	    let attacker_ids: Vec<ObjectId> = blocker_counts.keys().cloned().collect();
78	    let mut min_blockers: std::collections::HashMap<ObjectId, u32> = std::collections::HashMap::new();
79	    for &att_id in &attacker_ids {
80	        let mut min_req: u32 = 1; // default: any single creature can block
81	        // Menace keyword: need at least 2 blockers.
82	        if state.has_keyword(att_id, Keyword::Menace, registry) {
83	            min_req = min_req.max(2);
84	        }
85	        // MinimumBlockers continuous effects (e.g., Terror of Kruin Pass).
86	        for source in state.objects.values() {
87	            if source.zone != crate::types::Zone::Battlefield {
88	                continue;
89	            }
90	            let effects = if let Some(ref inst) = source.instance_continuous_effects {
91	                inst.clone()
92	            } else if let Some(behavior) = registry.get(source.card_id) {
93	                if source.is_transformed {
94	                    behavior.back_face_data().map(|d| d.continuous_effects).unwrap_or_default()
95	                } else {
96	                    behavior.card_data().continuous_effects
97	                }
98	            } else {
99	                vec![]
100	            };
101	            for effect in &effects {
102	                if let crate::types::ContinuousEffect::MinimumBlockers { count, scope } = effect {
103	                    if state.effect_applies_to(att_id, scope, source.id, source.controller, registry) {
104	                        min_req = min_req.max(*count);
105	                    }
106	                }
107	            }
108	        }
109	        if min_req > 1 {
110	            min_blockers.insert(att_id, min_req);
111	        }
112	    }
113	
114	    let valid: Vec<_> = valid.into_iter()
115	        .filter(|&(_, attacker)| {
116	            if let Some(&min) = min_blockers.get(&attacker) {
117	                blocker_counts.get(&attacker).copied().unwrap_or(0) >= min as usize
118	            } else {
119	                true
120	            }
121	        })
122	        .collect();
123	
124	    declare_blockers(state, &valid);
125	}
126	
127	/// Deal combat damage with full keyword support.
128	/// Handles first strike, trample, deathtouch, and lifelink.
129	pub fn deal_combat_damage(state: &mut GameState, registry: &CardRegistry) {
130	    let combat = match &state.combat {
131	        Some(c) => c.clone(),
132	        None => return,
133	    };
134	
135	    // Check if any creature has first/double strike to determine damage steps.
136	    let any_first_strike = combat.attackers.keys().chain(
137	        combat.blocker_assignments.values().flat_map(|v| v.iter())
138	    ).any(|&id| {
139	        state.has_keyword(id, Keyword::FirstStrike, registry)
140	            || state.has_keyword(id, Keyword::DoubleStrike, registry)
141	    });
142	
143	    if any_first_strike {
144	        // First strike damage step: only first/double strikers deal damage.
145	        deal_damage_step(state, &combat, registry, true);
146	        // Run SBAs between first strike and normal damage.
147	        while crate::sba::check_state_based_actions_with_registry(state, Some(registry)) {}
148	        // Normal damage step: non-first-strikers + double strikers.
149	        deal_damage_step(state, &combat, registry, false);
150	    } else {
151	        // No first strike: everyone deals damage simultaneously.
152	        deal_damage_step(state, &combat, registry, false);
153	    }
154	}
155	
156	/// Fight: each creature deals damage equal to its power to the other.
157	/// Used by Prey Upon and similar "fight" cards.
158	pub fn fight(state: &mut GameState, a: ObjectId, b: ObjectId, registry: &CardRegistry) {
159	    let power_a = state.effective_power(a, registry).unwrap_or(0).max(0) as u32;
160	    let power_b = state.effective_power(b, registry).unwrap_or(0).max(0) as u32;
161	
162	    if power_a > 0 {
163	        deal_damage_to_creature(state, a, b, power_a, registry);
164	    }
165	    if power_b > 0 {
166	        deal_damage_to_creature(state, b, a, power_b, registry);
167	    }
168	}
169	
170	/// Execute one combat damage step.
171	/// If `first_strike_only`, only creatures with first/double strike deal damage.
172	/// If not, creatures without first strike deal damage (plus double strikers again).
173	fn deal_damage_step(
174	    state: &mut GameState,
175	    combat: &CombatState,
176	    registry: &CardRegistry,
177	    first_strike_only: bool,
178	) {
179	    for (&attacker_id, &defending_player) in &combat.attackers {
180	        if state.get_object(attacker_id).map(|o| o.zone != Zone::Battlefield).unwrap_or(true) {
181	            continue;
182	        }
183	
184	        let has_fs = state.has_keyword(attacker_id, Keyword::FirstStrike, registry);
185	        let has_ds = state.has_keyword(attacker_id, Keyword::DoubleStrike, registry);
186	        let attacker_deals = if first_strike_only {
187	            has_fs || has_ds
188	        } else {
189	            !has_fs || has_ds // normal strikers + double strikers
190	        };
191	
192	        let attacker_power = if attacker_deals {
193	            state.effective_power(attacker_id, registry).unwrap_or(0).max(0) as u32
194	        } else {
195	            0
196	        };
197	
198	        let has_trample = state.has_keyword(attacker_id, Keyword::Trample, registry);
199	        let has_deathtouch_attacker = state.has_keyword(attacker_id, Keyword::Deathtouch, registry);
200	
201	        let blockers = combat.blocker_assignments.get(&attacker_id)
202	            .cloned()
203	            .unwrap_or_default();
204	
205	        if blockers.is_empty() {
206	            // Unblocked: deal damage to defending player.
207	            if attacker_power > 0 {
208	                deal_damage_to_player(state, attacker_id, defending_player, attacker_power, registry);
209	            }
210	        } else {
211	            // Blocked: distribute damage to blockers, with trample overflow.
212	            let mut remaining_power = attacker_power;
213	
214	            for &blocker_id in &blockers {
215	                if state.get_object(blocker_id).map(|o| o.zone != Zone::Battlefield).unwrap_or(true) {
216	                    continue;
217	                }
218	
219	                // Blocker deals damage to attacker.
220	                let blocker_has_fs = state.has_keyword(blocker_id, Keyword::FirstStrike, registry);
221	                let blocker_has_ds = state.has_keyword(blocker_id, Keyword::DoubleStrike, registry);
222	                let blocker_deals = if first_strike_only {
223	                    blocker_has_fs || blocker_has_ds
224	                } else {
225	                    !blocker_has_fs || blocker_has_ds
226	                };
227	
228	                if blocker_deals {
229	                    let blocker_power = state.effective_power(blocker_id, registry).unwrap_or(0).max(0) as u32;
230	                    if blocker_power > 0 {
231	                        deal_damage_to_creature(state, blocker_id, attacker_id, blocker_power, registry);
232	                    }
233	                }
234	
235	                // Attacker deals damage to blocker.
236	                if remaining_power > 0 {
237	                    let blocker_toughness = state.effective_toughness(blocker_id, registry).unwrap_or(0);
238	                    let blocker_damage = state.get_object(blocker_id).map(|o| o.damage_marked).unwrap_or(0);
239	                    let lethal = if has_deathtouch_attacker {
240	                        1 // deathtouch: 1 damage is lethal
241	                    } else {
242	                        (blocker_toughness - blocker_damage as i32).max(0) as u32
243	                    };
244	
245	                    let assigned = if has_trample {
246	                        remaining_power.min(lethal) // assign minimum lethal, save rest for trample
247	                    } else {
248	                        remaining_power // assign all to this blocker
249	                    };
250	
251	                    if assigned > 0 {
252	                        deal_damage_to_creature(state, attacker_id, blocker_id, assigned, registry);
253	                        remaining_power -= assigned;
254	                    }
255	                }
256	            }
257	
258	            // Trample: remaining damage goes to the defending player.
259	            if has_trample && remaining_power > 0 {
260	                deal_damage_to_player(state, attacker_id, defending_player, remaining_power, registry);
261	            }
262	        }
263	    }
264	}
265	
266	/// Check if a creature has a "prevent damage, remove counter" replacement effect
267	/// (e.g., Unbreathing Horde). If so, prevent the damage and remove a +1/+1 counter.
268	/// Returns true if damage was prevented.
269	fn apply_prevent_damage_remove_counter(state: &mut GameState, target: ObjectId, registry: &CardRegistry) -> bool {
270	    let has_effect = state.has_continuous_effect(target, &|e| {
271	        match e {
272	            crate::types::ContinuousEffect::PreventDamageRemoveCounter { scope } => Some(scope),
273	            _ => None,
274	        }
275	    }, registry);
276	    if has_effect {
277	        let counter_count = state.get_object(target)
278	            .and_then(|o| o.counters.get(&crate::types::CounterType::PlusOnePlusOne).copied())
279	            .unwrap_or(0);
280	        if counter_count > 0 {
281	            if let Some(obj) = state.get_object_mut(target) {
282	                let entry = obj.counters.entry(crate::types::CounterType::PlusOnePlusOne).or_insert(0);
283	                *entry = entry.saturating_sub(1);
284	                if *entry == 0 {
285	                    obj.counters.remove(&crate::types::CounterType::PlusOnePlusOne);
286	                }
287	            }
288	            let name = state.get_object(target).map(|o| o.name.clone()).unwrap_or_default();
289	            state.log(crate::state::LogLevel::Event,
290	                format!("{}: damage prevented, removed a +1/+1 counter", name));
291	        }
292	        // Damage is always prevented even if no counters remain.
293	        true
294	    } else {
295	        false
296	    }
297	}
298	
299	/// Check if a creature's combat damage should be prevented because it's not a Wolf/Werewolf
300	/// (set by Moonmist's effect for the rest of the turn).
301	fn is_non_wolf_damage_prevented(state: &GameState, source: ObjectId, registry: &CardRegistry) -> bool {
302	    if !state.prevent_non_wolf_werewolf_combat_damage {
303	        return false;
304	    }
305	    let subtypes = get_subtypes(state, source, registry);
306	    !subtypes.iter().any(|s| s == "Wolf" || s == "Werewolf")
307	}
308	
309	/// Compute the combat damage multiplier from DoubleCombatDamage effects (e.g., Inquisitor's Flail).
310	/// Each source doubles independently: 1 Flail = x2, 2 Flails = x4, 3 = x8, etc.
311	fn combat_damage_multiplier(state: &GameState, creature_id: ObjectId, registry: &CardRegistry) -> u32 {
312	    let count = state.count_continuous_effect(creature_id, &|e| {
313	        match e {
314	            crate::types::ContinuousEffect::DoubleCombatDamage { scope } => Some(scope),
315	            _ => None,
316	        }
317	    }, registry);
318	    1u32 << count // 2^count
319	}
320	
321	/// Check if a creature has combat damage prevented (e.g., Ghostly Possession).
322	fn has_damage_prevention(state: &GameState, creature_id: ObjectId, registry: &CardRegistry) -> bool {
323	    state.has_continuous_effect(creature_id, &|e| {
324	        match e {
325	            crate::types::ContinuousEffect::PreventCombatDamage { scope } => Some(scope),
326	            _ => None,
327	        }
328	    }, registry)
329	}
330	
331	/// Check if a creature has protection from a specific subtype.
332	fn has_protection_from(state: &GameState, creature_id: ObjectId, subtype: &str, registry: &CardRegistry) -> bool {
333	    for source in state.objects.values() {
334	        if source.zone != crate::types::Zone::Battlefield {
335	            continue;
336	        }
337	        let effects = if let Some(ref instance_effects) = source.instance_continuous_effects {
338	            instance_effects.clone()
339	        } else if let Some(behavior) = registry.get(source.card_id) {
340	            behavior.card_data().continuous_effects
341	        } else {
342	            continue;
343	        };
344	        for effect in &effects {
345	            if let crate::types::ContinuousEffect::ProtectionFromSubtype { subtype: prot_sub, scope } = effect {
346	                if prot_sub == subtype && state.effect_applies_to(creature_id, scope, source.id, source.controller, registry) {
347	                    return true;
348	                }
349	            }
350	        }
351	    }
352	    false
353	}
354	
355	/// Get all subtypes of a creature (from both card data and object-level subtypes).
356	fn get_subtypes(state: &GameState, creature_id: ObjectId, registry: &CardRegistry) -> Vec<String> {
357	    let mut subtypes = Vec::new();
358	    if let Some(obj) = state.get_object(creature_id) {
359	        subtypes.extend(obj.subtypes.iter().cloned());
360	        if let Some(data) = registry.card_data(obj.card_id) {
361	            for s in &data.subtypes {
362	                if !subtypes.contains(s) {
363	                    subtypes.push(s.clone());
364	                }
365	            }
366	        }
367	    }
368	    subtypes
369	}
370	
371	/// Check if creature_a has protection from creature_b.
372	/// Checks all protection-from-subtype effects and until-EOT protection grants.
373	fn has_protection_from_creature(state: &GameState, protected: ObjectId, attacker: ObjectId, registry: &CardRegistry) -> bool {
374	    let attacker_subtypes = get_subtypes(state, attacker, registry);
375	
376	    // Check static protection-from-subtype effects.
377	    for subtype in &attacker_subtypes {
378	        if has_protection_from(state, protected, subtype, registry) {
379	            return true;
380	        }
381	    }
382	
383	    // Check static ProtectionFrom (filter-based) effects.
384	    for source in state.objects.values() {
385	        if source.zone != crate::types::Zone::Battlefield {
386	            continue;
387	        }
388	        let effects = if let Some(ref instance_effects) = source.instance_continuous_effects {
389	            instance_effects.clone()
390	        } else if let Some(behavior) = registry.get(source.card_id) {
391	            behavior.card_data().continuous_effects
392	        } else {
393	            continue;
394	        };
395	        for effect in &effects {
396	            if let crate::types::ContinuousEffect::ProtectionFrom { filter, scope } = effect {
397	                if state.effect_applies_to(protected, scope, source.id, source.controller, registry) {
398	                    if state.matches_filter(attacker, filter, source.controller, registry) {
399	                        return true;
400	                    }
401	                }
402	            }
403	        }
404	    }
405	
406	    // Check until-end-of-turn protection grants.
407	    for prot in &state.until_end_of_turn_protection {
408	        if prot.target == protected {
409	            // Check if the attacker matches the filter.
410	            // Use controller of the protected creature for filter context.
411	            let controller = state.get_object(protected).map(|o| o.controller).unwrap_or(crate::ids::PlayerId(0));
412	            if state.matches_filter(attacker, &prot.filter, controller, registry) {
413	                return true;
414	            }
415	        }
416	    }
417	
418	    false
419	}
420	
421	/// Deal damage from a source creature to a target creature. Handles lifelink.
422	fn deal_damage_to_creature(
423	    state: &mut GameState,
424	    source: ObjectId,
425	    target: ObjectId,
426	    amount: u32,
427	    registry: &CardRegistry,
428	) {
429	    // Skip if source or target has combat damage prevention (e.g., Ghostly Possession).
430	    if has_damage_prevention(state, source, registry) || has_damage_prevention(state, target, registry) {
431	        return;
432	    }
433	
434	    // Moonmist: prevent combat damage from non-Wolf/non-Werewolf creatures.
435	    if is_non_wolf_damage_prevented(state, source, registry) {
436	        return;
437	    }
438	
439	    // Protection: if target has protection from the source creature, prevent damage.
440	    if has_protection_from_creature(state, target, source, registry) {
441	        return;
442	    }
443	
444	    // Unbreathing Horde: prevent damage, remove counter.
445	    if apply_prevent_damage_remove_counter(state, target, registry) {
446	        return;
447	    }
448	
449	    // Inquisitor's Flail: multiply damage for each DoubleCombatDamage source.
450	    // Dealing: source's Flails multiply the damage dealt.
451	    // Receiving: target's Flails multiply the damage received.
452	    let mut amount = amount;
453	    amount *= combat_damage_multiplier(state, source, registry);
454	    amount *= combat_damage_multiplier(state, target, registry);
455	
456	    let has_deathtouch = state.has_keyword(source, Keyword::Deathtouch, registry);
457	    if let Some(obj) = state.get_object_mut(target) {
458	        obj.damage_marked += amount;
459	        if has_deathtouch {
460	            obj.dealt_deathtouch_damage = true;
461	        }
462	        // Track which creatures dealt damage to this creature (for Abattoir Ghoul).
463	        if !obj.damaged_by.contains(&source) {
464	            obj.damaged_by.push(source);
465	        }
466	    }
467	    state.events.push(GameEvent::CombatDamageDealt {
468	        source,
469	        target: DamageTarget::Object(target),
470	        amount,
471	    });
472	
473	    // Lifelink: source's controller gains life.
474	    if state.has_keyword(source, Keyword::Lifelink, registry) {
475	        let controller = state.get_object(source).expect("damage source must exist").controller;
476	        let old_life = state.get_player(controller).life;
477	        let new_life = old_life + amount as i32;
478	        state.get_player_mut(controller).life = new_life;
479	        state.events.push(GameEvent::LifeChanged {
480	            player: controller,
481	            old: old_life,
482	            new_life,
483	        });
484	    }
485	}
486	
487	/// Deal damage from a source creature to a player. Handles lifelink.
488	fn deal_damage_to_player(
489	    state: &mut GameState,
490	    source: ObjectId,
491	    player: PlayerId,
492	    amount: u32,
493	    registry: &CardRegistry,
494	) {
495	    // Skip if source has combat damage prevention (e.g., Ghostly Possession).
496	    if has_damage_prevention(state, source, registry) {
497	        return;
498	    }
499	
500	    // Moonmist: prevent combat damage from non-Wolf/non-Werewolf creatures.
501	    if is_non_wolf_damage_prevented(state, source, registry) {
502	        return;
503	    }
504	
505	    // Inquisitor's Flail: multiply damage for each DoubleCombatDamage source.
506	    let mut amount = amount;
507	    amount *= combat_damage_multiplier(state, source, registry);
508	
509	    let old_life = state.get_player(player).life;
510	    let new_life = old_life - amount as i32;
511	    state.get_player_mut(player).life = new_life;
512	
513	    state.events.push(GameEvent::CombatDamageDealt {
514	        source,
515	        target: DamageTarget::Player(player),
516	        amount,
517	    });
518	    state.events.push(GameEvent::LifeChanged {
519	        player,
520	        old: old_life,
521	        new_life,
522	    });
523	
524	    let name = state.get_object(source)
525	        .map(|o| {
526	            // Use object name directly (works for tokens); fall back to registry.
527	            if !o.name.is_empty() {
528	                o.name.clone()
529	            } else {
530	                registry.card_data(o.card_id)
531	                    .map(|d| d.name)
532	                    .unwrap_or_else(|| "?".into())
533	            }
534	        })
535	        .unwrap_or_else(|| "?".into());
536	    state.log(LogLevel::Event, format!("p{} took {} combat damage ({}) from {}", player.0, amount, new_life, name));
537	
538	    // Lifelink: source's controller gains life.
539	    if state.has_keyword(source, Keyword::Lifelink, registry) {
540	        let controller = state.get_object(source).expect("damage source must exist").controller;
541	        let old = state.get_player(controller).life;
542	        let new = old + amount as i32;
543	        state.get_player_mut(controller).life = new;
544	        state.events.push(GameEvent::LifeChanged {
545	            player: controller,
546	            old,
547	            new_life: new,
548	        });
549	    }
550	}
