1	//! Tests for proper spell fizzle implementation (CR 608.2b).
2	//!
3	//! A spell whose targets are all illegal when it tries to resolve should
4	//! be countered by game rules BEFORE on_resolve is called. This is different
5	//! from on_resolve checking targets and doing nothing — the spell should
6	//! never resolve at all.
7	//!
8	//! These tests verify the mechanism, not just the outcome.
9	
10	mod common;
11	
12	use common::*;
13	use mtg_engine::actions::{Action, Target};
14	use mtg_engine::cards::CardRegistry;
15	use mtg_engine::engine;
