83	// ════════════════════════════════════════════════════════════════════
84	// Mechanism test: on_resolve should NOT be called for fizzle
85	//
86	// We test this using Swords to Plowshares, which exiles a creature
87	// AND causes its controller to gain life. If on_resolve runs but the
88	// zone check saves us, the life gain won't happen — but that's the
89	// wrong reason. We verify via the SpellResolved event instead.
90	//
91	// More importantly: if someone later writes a card that does
92	// "deal damage to target creature; draw a card", the fizzle must
93	// prevent BOTH effects. We simulate this with a two-part test.
94	// ════════════════════════════════════════════════════════════════════
95	
96	/// Swords to Plowshares fizzle: no exile, no life gain, no SpellResolved.
97	#[test]
98	fn swords_fizzle_no_side_effects() {
99	    let reg = registry();
100	    let mut state = game_at_step(Step::PrecombatMain, P0);
101	
102	    let creature = ready_creature(&mut state, P1, 5, 5);
103	    let swords = castable_spell(&mut state, &reg, "Swords to Plowshares", P0);
104	
105	    state = engine::submit_action(
106	        &state,
107	        &Action::CastSpell { object_id: swords, targets: vec![Target::Object(creature)], sacrifice: None, exile_count: None, alternative_cost: None },
108	        &reg,
109	    );
110	
