140	
141	    // Put Geistflame in graveyard (for flashback).
142	    let gf_id = reg.get_id_by_name("Geistflame").unwrap();
143	    let geistflame = state.create_object(gf_id, P0, Zone::Graveyard, None, None);
144	    state.get_object_mut(geistflame).unwrap().name = "Geistflame".into();
145	
