154	        &state,
155	        &Action::CastSpell { object_id: geistflame, targets: vec![Target::Object(creature)], sacrifice: None, exile_count: None, alternative_cost: None },
156	        &reg,
157	    );
158	    assert!(state.get_object(geistflame).unwrap().cast_with_flashback);
159	
160	    // Target dies before resolution.
161	    state.move_object(creature, Zone::Graveyard);
162	
163	    mtg_engine::stack::resolve_top_of_stack(&mut state, &reg);
